sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.uhr-dashboard {
  display: flex;
  min-height: 100vh;
  background: #f7f9fc;
  font-family: Arial, sans-serif;
  color: #0f1b45;
}

.sn-sidebar {
  width: 275px;
  min-width: 275px;
  min-height: 100vh;
  background: #062f3d;
  color: #ffffff;
  padding: 18px 14px;
  display: flex;
  flex-direction: column;
  box-shadow: 2px 0 8px rgba(0,0,0,.08);
}

.sn-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 10px 18px;
  border-bottom: 1px solid rgba(255,255,255,.12);
  margin-bottom: 16px;
}

.sn-logo-mark {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: #81d742;
  color: #052e3a;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 17px;
}

.sn-brand-title {
  font-size: 17px;
  font-weight: 700;
}

.sn-brand-sub {
  font-size: 11px;
  color: #b9ccd3;
  margin-top: 2px;
}

.sn-search {
  height: 38px;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 5px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  margin-bottom: 15px;
}

.sn-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #ffffff;
  font-size: 13px;
}

.bell {
    cursor: pointer;
    text-decoration: none;
    font-size: 20px;
}

.sn-search input::placeholder {
  color: #c9d7dc;
}

.sn-search-icon {
  color: #dce8ec;
}

.sn-nav {
  flex: 1;
}

.sn-nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 42px;
  padding: 0 12px;
  margin: 2px 0;
  color: #e7f0f3 !important;
  text-decoration: none !important;
  border-radius: 5px;
  font-size: 13px;
  transition: .18s ease;
}

.sn-nav-item:hover,
.sn-sub-item:hover {
  background: rgba(255,255,255,.10);
  color: #ffffff !important;
}

.sn-nav-item.active {
  background: #164a5b;
  box-shadow: inset 3px 0 0 #81d742;
  color: #ffffff !important;
  font-weight: 600;
}

.sn-nav-icon {
  width: 20px;
  text-align: center;
  font-size: 15px;
}

.sn-section {
  margin: 5px 0 8px;
}

.sn-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #b8cbd2;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .45px;
  padding: 10px 12px 6px;
}

.sn-chevron {
  font-size: 12px;
  color: #95b1bb;
}

.sn-sub-item {
  display: block;
  color: #e6eef1 !important;
  text-decoration: none !important;
  font-size: 13px;
  padding: 9px 12px 9px 43px;
  border-radius: 5px;
  margin: 1px 0;
}

.sn-count {
  margin-left: auto;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border-radius: 11px;
  background: #81d742;
  color: #062f3d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

.sn-help-card {
  margin-top: 18px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 9px;
  padding: 17px 14px;
  text-align: center;
}

.sn-help-icon {
  width: 40px;
  height: 40px;
  margin: 0 auto 10px;
  border-radius: 50%;
  background: rgba(129,215,66,.18);
  color: #81d742;
  display: flex;
  align-items: center;
  justify-content: center;
}

.sn-help-card strong {
  display: block;
  font-size: 14px;
}

.sn-help-card p {
  color: #bdd0d6;
  font-size: 11px;
  line-height: 1.5;
  margin: 6px 0 12px;
}

.sn-help-card button {
  width: 100%;
  border: 0;
  border-radius: 5px;
  background: #81d742;
  color: #062f3d;
  padding: 9px 8px;
  font-size: 12px;
  font-weight: 700;
}

.brand-icon {
  font-size: 28px;
}

.brand-text {
  font-size: 24px;
  font-weight: 700;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 15px;
  margin-bottom: 5px;
  border-radius: 8px;
  text-decoration: none !important;
  color: #17234d !important;
  font-size: 14px;
}

.nav-item:hover {
  background: #f2f4fa;
}

.nav-item.active {
  background: #1b2858;
  color: white !important;
}

.help-card {
  margin-top: auto;
  padding: 20px;
  border: 1px solid #e6e9ef;
  border-radius: 14px;
  text-align: center;
  background: #fbfcff;
}

.help-icon {
  font-size: 35px;
  margin-bottom: 8px;
}

.help-card button {
  width: 100%;
  border: none;
  border-radius: 6px;
  padding: 10px;
  background: #15265b;
  color: white;
}

.uhr-main {
  flex: 1;
  padding: 28px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 26px;
}

.topbar h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
}

.topbar p {
  margin-top: 7px;
  color: #667085;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 15px;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  background: white;
  border: 1px solid #e4e7ec;
  border-radius: 12px;
  padding: 10px 14px;
  min-width: 300px;
}

.search-box input {
  border: none;
  outline: none;
  width: 100%;
}

.profile-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #eef1f7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.profile-box small {
  display: block;
  color: #667085;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 22px;
}

.stat-card {
  background: white;
  border: 1px solid #e6e9ef;
  border-radius: 16px;
  padding: 22px;
  min-height: 190px;
  box-shadow: 0 3px 12px rgba(0,0,0,.04);
}

.stat-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 25px;
  margin-bottom: 14px;
}

.green { background: #e7f8f2; }
.blue { background: #edf3ff; }
.purple { background: #f3edff; }
.orange { background: #fff2e8; }

.stat-title {
  font-size: 16px;
  font-weight: 700;
}

.stat-value {
  font-size: 34px;
  font-weight: 700;
  margin: 8px 0 18px;
}

.stat-value span {
  font-size: 13px;
  font-weight: 500;
}

.stat-card a {
  text-decoration: none;
}

.stat-date {
  font-size: 28px;
  font-weight: 700;
  margin-top: 14px;
}

.stat-sub,
.stat-empty {
  margin-top: 5px;
  color: #667085;
}

.content-grid,
.bottom-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 20px;
  margin-bottom: 22px;
}

.panel {
  background: white;
  border: 1px solid #e6e9ef;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(0,0,0,.04);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.panel-header h3 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 12px 10px;
  border-bottom: 1px solid #edf0f4;
  text-align: left;
  font-size: 13px;
}

th {
  background: #fafbfc;
}

.status-pill {
  padding: 5px 10px;
  border-radius: 12px;
  background: #fff3d6;
  font-size: 12px;
}

.empty-row {
  text-align: center;
  color: #667085;
}

.announcement {
  display: flex;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid #edf0f4;
}

.dot {
  width: 8px;
  height: 8px;
  background: #2f6fed;
  border-radius: 50%;
  margin-top: 7px;
}

.announcement p {
  margin: 4px 0 0;
  color: #667085;
  font-size: 12px;
}

.quick-actions {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.quick-actions a {
  padding: 18px 10px;
  border: 1px solid #e6e9ef;
  border-radius: 12px;
  text-align: center;
  text-decoration: none;
  color: #182450;
}

.quick-icon {
  font-size: 28px;
  margin-bottom: 8px;
}

.shortcut-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.shortcut-grid a {
  background: #f5f8ff;
  padding: 14px;
  border-radius: 10px;
  text-decoration: none;
}

.leave-progress {
  height: 7px;
  background: #edf1f5;
  border-radius: 20px;
  margin: 14px 0;
  overflow: hidden;
}

.leave-progress-bar {
  height: 100%;
  background: #21b383;
  border-radius: 20px;
}

.status-approved {
  background: #e8f7ef;
  color: #12805c;
}

.status-rejected {
  background: #fdecec;
  color: #d92d20;
}

.status-pending {
  background: #fff4d8;
  color: #d97706;
}

@media (max-width: 1200px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .content-grid,
  .bottom-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .uhr-sidebar {
    display: none;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .quick-actions {
    grid-template-columns: repeat(2, 1fr);
  }

  .top-actions {
    display: none;
  }
}

@media (max-width: 900px) {
  .sn-sidebar {
    display: none;
  }
}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName();

    var initials = "";
    var parts = data.userName.split(" ");

    for (var i = 0; i < parts.length && i < 2; i++) {
        if (parts[i])
            initials += parts[i].charAt(0).toUpperCase();
    }

    data.initials = initials;

    data.totalBalance = 0;
	data.maxLeaveBalance = 37;
    data.leaveRequestCount = 0;
    data.hrCaseCount = 0;
    data.recentLeaves = [];
    data.upcomingLeave = null;

    var balanceGR = new GlideRecord('x_snc_unified_hr_0_leave_balance');
    balanceGR.addQuery('employee', gs.getUserID());
    balanceGR.setLimit(1);
    balanceGR.query();

    if (balanceGR.next()) {

        var casual = parseInt(balanceGR.getValue('casual_leave_balance') || 0, 10);
        var sick = parseInt(balanceGR.getValue('sick_leave_balance') || 0, 10);
        var earned = parseInt(balanceGR.getValue('earned_leave_balance') || 0, 10);

        data.totalBalance = casual + sick + earned;

		data.balancePercent = Math.min(
			Math.round((data.totalBalance / data.maxLeaveBalance) * 100),
			100
		);
    }

    var leaveCountGR = new GlideAggregate('x_snc_unified_hr_0_leave_request');
    leaveCountGR.addQuery('requested_by', gs.getUserID());
    leaveCountGR.addAggregate('COUNT');
    leaveCountGR.query();

    if (leaveCountGR.next())
        data.leaveRequestCount = parseInt(leaveCountGR.getAggregate('COUNT'), 10);

    var recentGR = new GlideRecord('x_snc_unified_hr_0_leave_request');
    recentGR.addQuery('requested_by', gs.getUserID());
    recentGR.orderByDesc('applied_on');
    recentGR.setLimit(4);
    recentGR.query();

    while (recentGR.next()) {

        data.recentLeaves.push({
            number: recentGR.getDisplayValue('number'),
            leave_type: recentGR.getDisplayValue('leave_type'),
            start_date: recentGR.getDisplayValue('start_date'),
            end_date: recentGR.getDisplayValue('end_date'),
            status: recentGR.getDisplayValue('status'),
			hod_remarks: recentGR.getValue('hod_remarks') || "-",
			hr_remarks: recentGR.getValue('hr_remarks') || "-"
        });
    }

    var upcomingGR = new GlideRecord('x_snc_unified_hr_0_leave_request');
    upcomingGR.addQuery('requested_by', gs.getUserID());
    upcomingGR.addQuery('status', 'Approved');
    upcomingGR.addQuery('start_date', '>=', new GlideDate().getValue());
    upcomingGR.orderBy('start_date');
    upcomingGR.setLimit(1);
    upcomingGR.query();

    if (upcomingGR.next()) {

        data.upcomingLeave = {
            start_date: upcomingGR.getDisplayValue('start_date'),
            leave_type: upcomingGR.getDisplayValue('leave_type')
        };
    }


	data.announcements = [];

var now = new GlideDateTime();

// Find the current Service Portal record
var portalGR = new GlideRecord('sp_portal');
portalGR.addQuery('url_suffix', 'sp');
portalGR.setLimit(1);
portalGR.query();

if (portalGR.next()) {

    var portalId = portalGR.getUniqueValue();

    // Find announcements linked to this portal
    var relGR = new GlideRecord('m2m_announcement_portal');
    relGR.addQuery('sp_portal', portalId);
    relGR.query();

    var announcementIds = [];

    while (relGR.next()) {
        announcementIds.push(relGR.getValue('announcement'));
    }

    if (announcementIds.length > 0) {

        var annGR = new GlideRecord('announcement');
        annGR.addQuery('sys_id', 'IN', announcementIds.join(','));
        annGR.addQuery('active', true);
        annGR.addQuery('from', '<=', now);

        var qc = annGR.addQuery('to', '>=', now);
        qc.addOrCondition('to', '');

        annGR.orderByDesc('from');
        annGR.setLimit(3);
        annGR.query();

        while (annGR.next()) {
            data.announcements.push({
                title: annGR.getDisplayValue('title'),
                summary: annGR.getDisplayValue('summary')
            });
        }
    }
}
// ==============================
// Active HR Case Count
// ==============================

data.hrCaseCount = 0;

var caseGR = new GlideRecord('x_snc_unified_hr_0_hr_case');

caseGR.addQuery('request_by', gs.getUserID());
caseGR.query();

while (caseGR.next()) {

    var caseStatus = (
        caseGR.getDisplayValue('status') || ""
    ).toLowerCase();

    if (
        caseStatus != 'resolved' &&
        caseStatus != 'closed' &&
        caseStatus != 'cancelled' &&
        caseStatus != 'canceled'
    ) {
        data.hrCaseCount++;
    }
}



	// ==============================
	// Notification Count
	// ==============================

	data.notificationCount = 0;

	var notificationGR = new GlideAggregate('ui_notification_inbox');

	notificationGR.addQuery('recipient', gs.getUserID());
	notificationGR.addQuery('status', '!=', 'deleted');
	notificationGR.addAggregate('COUNT');

	notificationGR.query();

	if (notificationGR.next()) {
		data.notificationCount = parseInt(
			notificationGR.getAggregate('COUNT'),
			10
		) || 0;
	}

})();
